CREATE OR REPLACE VIEW mktg_ops_vws.bz_dim_intrctn_status AS 
SELECT CASE WHEN ((adb_enumrtn_lkp.enumrtn_cd)::text = (0)::text) THEN 1 WHEN ((adb_enumrtn_lkp.enumrtn_cd)::text = (1)::text) THEN 2 WHEN ((adb_enumrtn_lkp.enumrtn_cd)::text = (2)::text) THEN 3 WHEN ((adb_enumrtn_lkp.enumrtn_cd)::text = (3)::text) THEN 4 WHEN ((adb_enumrtn_lkp.enumrtn_cd)::text = (5)::text) THEN 5 WHEN ((adb_enumrtn_lkp.enumrtn_cd)::text = (6)::text) THEN 6 WHEN ((adb_enumrtn_lkp.enumrtn_cd)::text = (7)::text) THEN 7 WHEN ((adb_enumrtn_lkp.enumrtn_cd)::text = (8)::text) THEN 8 WHEN ((adb_enumrtn_lkp.enumrtn_cd)::text = (9)::text) THEN 9 WHEN ((adb_enumrtn_lkp.enumrtn_cd)::text = (127)::text) THEN 10 ELSE 999 END AS intrctn_status_key, (adb_enumrtn_lkp.enumrtn_cd)::smallint AS intrctn_status_id, adb_enumrtn_lkp.enumrtn_dsc AS intrctn_status_dsc FROM mktg_ops_tbls.adb_enumrtn_lkp WHERE ((adb_enumrtn_lkp.enumrtn_label)::text = 'intrctn_status_dsc'::text) UNION SELECT 0 AS intrctn_status_key, (999)::smallint AS intrctn_status_id, 'Unknown' AS intrctn_status_dsc FROM mktg_ops_tbls.adb_enumrtn_lkp WITH NO SCHEMA BINDING;